// AI对话业务: 状态=messages/loading/error 方法=sendMessage/generateQuestions/stop/clear | 数据流: 用户输入 → SSE流 → messages数组 → localStorage
import { ref, reactive, onMounted, onUnmounted } from 'vue'
import { chatStream, generateStream } from '../api/ai'

const STORAGE_KEY = 'ai_chat_messages'
const MAX_TOKENS = 4000

export function useAiChat() {
  const messages = ref([])
  const loading = ref(false)
  const error = ref(null)
  const tokenWarning = ref(null)
  const sseState = reactive({ close: null, retryCount: 0 })

  // 持久化
  function saveToLocalStorage() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(messages.value)) } catch (e) { }
  }
  function loadFromLocalStorage() {
    try { const saved = localStorage.getItem(STORAGE_KEY); if (saved) messages.value = JSON.parse(saved) } catch (e) { }
  }

  // Token估算与裁剪
  function estimateTokens(msgs) {
    return msgs.reduce((sum, m) => sum + Math.ceil(m.content.length * 0.5), 0)
  }
  function trimMessages() {
    if (estimateTokens(messages.value) <= MAX_TOKENS) return
    const maxMessages = 10  // 保留最近5轮对话
    if (messages.value.length > maxMessages) {
      const removed = messages.value.length - maxMessages
      messages.value = messages.value.slice(-maxMessages)
      tokenWarning.value = `对话过长，已裁剪最早${removed}条消息`
      setTimeout(() => { tokenWarning.value = null }, 3000)
    }
  }

  // SSE调用
  function abortCurrent() { if (sseState.close) { sseState.close(); sseState.close = null } }
  function callSSE(type, input, onComplete) {
    abortCurrent()
    loading.value = true
    error.value = null
    sseState.retryCount = 0
    trimMessages()
    const onMessage = (data) => {
      if (data.type === 'content') {
        const last = messages.value[messages.value.length - 1]
        if (last && last.role === 'assistant') { last.content += data.content; saveToLocalStorage() }
      } else if (data.type === 'status' && data.status === 'done') {
        loading.value = false; saveToLocalStorage(); if (onComplete) onComplete()
      } else if (data.type === 'error') { handleError(data.error, type, input, onComplete) }
    }
    const onError = (e) => { handleError(e.message || '连接失败', type, input, onComplete) }
    sseState.close = type === 'chat' ? chatStream(input, onMessage, onError) : generateStream(input, onMessage, onError)
  }

  // 错误处理（带重试）
  function handleError(errMsg, type, input, onComplete) {
    if ((errMsg.includes('timeout') || errMsg.includes('network')) && sseState.retryCount < 1) {
      sseState.retryCount++; error.value = '连接中断，正在重试...'; setTimeout(() => callSSE(type, input, onComplete), 1000); return
    }
    loading.value = false
    if (errMsg.includes('timeout')) error.value = 'AI响应超时，请稍后重试'
    else if (errMsg.includes('format') || errMsg.includes('JSON')) error.value = 'AI返回格式异常，请重试'
    else if (errMsg.includes('network') || errMsg.includes('fetch')) error.value = '网络异常，请检查连接'
    else error.value = errMsg
  }

  // 公共方法
  function sendMessage(content) {
    if (!content.trim()) return
    messages.value.push({ role: 'user', content }); messages.value.push({ role: 'assistant', content: '' })
    saveToLocalStorage(); callSSE('chat', content)
  }
  function generateQuestions(params) {
    const prompt = `请生成一道${params.category}方向的${params.difficulty}难度面试题`
    messages.value.push({ role: 'user', content: prompt }); messages.value.push({ role: 'assistant', content: '' })
    saveToLocalStorage(); callSSE('generate', prompt)
  }
  function stop() { abortCurrent(); loading.value = false }
  function clear() { messages.value = []; localStorage.removeItem(STORAGE_KEY) }

  onMounted(() => { loadFromLocalStorage() })
  onUnmounted(() => { abortCurrent() })

  return { messages, loading, error, tokenWarning, sendMessage, generateQuestions, stop, clear }
}
